import{_ as a}from"./chunks/exchange.WBTyBzew.js";import{_ as t,o as r,c as s,a2 as o}from"./chunks/framework.CqGS6Fr9.js";const g=JSON.parse('{"title":"Wallet, mail and market","description":"","frontmatter":{"pageId":"players/economy","contentRevision":6},"headers":[],"relativePath":"en/players/economy.md","filePath":"en/players/economy.md"}'),n={name:"en/players/economy.md"};function l(i,e,c,d,h,p){return r(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="wallet-mail-and-market" tabindex="-1">Wallet, mail and market <a class="header-anchor" href="#wallet-mail-and-market" aria-label="Permalink to &quot;Wallet, mail and market&quot;">​</a></h1><p>Applies to: Rimlink 0.9.2 · RimWorld 1.7 · protocol 1.</p><img class="wiki-art" src="'+a+'" alt="Exchanges use server escrow; deliveries arrive through the mailbox." width="960" height="440"><p class="wiki-caption">Exchanges use server escrow; deliveries arrive through the mailbox.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage {#usage}&quot;">​</a></h2><ol class="flow-diagram" aria-label="Process diagram"><li><strong>Intent</strong><span>Goods/pawns/wallet and original request ID.</span></li><li><strong>Snapshot</strong><span>Journal and exact home-map acceptance.</span></li><li><strong>Escrow</strong><span>Server retains until settlement or cancellation.</span></li><li><strong>Mailbox</strong><span>Receive → save → acknowledge.</span></li></ol><p>Normal operations require a comms console and powered trade beacons; goods are selected from their served area. The wallet is a server silver balance, not a physical stack. Depositing moves silver into that balance; withdrawal arrives through a server parcel.</p><p>List items or a pawn as an ordinary lot, set a price and review its contents. The buyer pays from the wallet, goods enter delivery and the seller receives proceeds minus any fee. Unsold lots expire after 30 days by default.</p><p>Check mail after a transaction or disconnect. The server holds outgoing goods in escrow until settlement and returns them through parcels.</p><h2 id="wallet-market" tabindex="-1">How do I deposit silver, buy and receive goods? <a class="header-anchor" href="#wallet-market" aria-label="Permalink to &quot;How do I deposit silver, buy and receive goods? {#wallet-market}&quot;">​</a></h2><p>Select a colonist → right-click the <strong>comms console</strong> → <strong>Rimlink</strong>. Eligible items come from powered orbital trade beacon areas. A wallet is a server balance; silver stacks on the floor do not enter it automatically.</p><ol><li>Place silver under a beacon. In <strong>Wallet</strong>, deposit it and wait for the save/transfer operation.</li><li>Open the market, inspect the lot contents, price and seller. Purchases spend wallet silver.</li><li>After success, check balance and <strong>Mailbox</strong>. Return to your home map for a drop pod; <strong>Accept now</strong> requests immediate delivery.</li><li>Place <strong>Architect → Misc → Rimlink delivery spot</strong> to select a landing area. Without one, the first beacon or normal trade-pod spot is used.</li><li>To obtain physical silver again, withdraw from the wallet and receive the parcel at home.</li></ol><p>If someone bought the lot first, refresh and choose another. Do not send the seller a separate payment. A server wallet grants no access to another alliance member&#39;s funds.</p><h2 id="selling-fees" tabindex="-1">How do I sell, and why can a balance become negative? <a class="header-anchor" href="#selling-fees" aria-label="Permalink to &quot;How do I sell, and why can a balance become negative? {#selling-fees}&quot;">​</a></h2><p>In <strong>My lots</strong>, select items or one pawn, set a price and confirm dispatch. Goods leave the map for escrow until sold. <strong>Withdraw</strong> returns a lot by mail; unsold lots return after 30 days by default. Selling a colonist is a real departure with skills, health and equipment, not a copy.</p><p>Default storage is 0.5% of value per real day after three free days <strong>for pawns and perishable goods</strong>, not every steel ingot. It is charged when goods leave storage. A lot pays from proceeds and then the wallet, potentially creating debt. A delivered parcel cannot charge more than the available wallet. Check server policy.</p><p>Debt blocks purchases, new lots and sends; depositing silver or making sales can repay it. Threat blocks new outflow, while receiving, purchases, withdrawing a lot and mail continue. Wallets, lots and pending goods count toward wealth: escrow is not a way to hide assets from protection or raids.</p><p>Gift, trade and raid-parcel values declared by another player retain their established trust rules. A protected UUID/custody link preserves those rules, including a gift awaiting a decision. Server-valued outpost production and actual currency escrow are accounted for separately. A mixed own-return parcel includes the full item value with stack quantities alongside its pawn. Physical import is credited once from the complete bound contents, including older parcels with a partial stored valuation. Silver credited to the wallet is accounted for separately from physical goods.</p><h2 id="exchange-recovery" tabindex="-1">What if the transfer response is lost? <a class="header-anchor" href="#exchange-recovery" aria-label="Permalink to &quot;What if the transfer response is lost? {#exchange-recovery}&quot;">​</a></h2><p>Removing goods journals the transfer and creates an exact snapshot. The server operation proceeds after that snapshot is accepted. A lost response is not a refusal: replay the <strong>original request</strong>, not a new sale of the same items. Reconnect and inspect lot/mail/balance. A definitive refusal returns contents once; its journal remains until that return is saved.</p><p>Do not delete the outbox or load a pre-transfer save. Preserve files, time and operation ID if manual help is required. A parcel absent from mail and a delivered parcel awaiting snapshot confirmation are different states.</p><h2 id="limits" tabindex="-1">Limits and safety <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits and safety {#limits}&quot;">​</a></h2><p>By default storage costs 0.5% per day after 3 free days. Debt, map threats, freezes or forbidden defNames can restrict operations. Fees and limits are server-configurable.</p><h2 id="related" tabindex="-1">See also <a class="header-anchor" href="#related" aria-label="Permalink to &quot;See also {#related}&quot;">​</a></h2><ul><li><a href="./gifts-trades">Gifts and two-way trades</a></li><li><a href="./auctions">Auctions</a></li><li><a href="./procurement">Orders, contracts and shared goals</a></li></ul>',25)])])}const f=t(n,[["render",l]]);export{g as __pageData,f as default};
